#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    vector<long long> a(n);
    for (auto &x : a) scanf("%lld", &x);
    sort(a.rbegin(), a.rend());  // largest first
    long long total = 0;
    int count = 0;
    for (long long v : a) {
        if (total + v <= 0) break;  // every remaining value is no larger
        total += v;
        count++;
    }
    printf("%d\n", count);
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken(); int n = (int) st.nval;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) { st.nextToken(); a[i] = (long) st.nval; }
        Arrays.sort(a);
        long total = 0;
        int count = 0;
        for (int i = n - 1; i >= 0; i--) { // largest first
            if (total + a[i] <= 0) break;  // every remaining value is no larger
            total += a[i];
            count++;
        }
        System.out.println(count);
    }
}
